args.content:
// Minimal argparse mimic for this script's CLI: three required options
// --a (str), --b (str), --c (int), plus -h/--help.
// Reproduces Python argparse's usage/error format and exit codes.

import process from 'node:process';

// argparse uses basename(sys.argv[0]) as the program name.
function progName() {
  const p = process.argv[1] || '';
  const parts = p.split('/');
  return parts[parts.length - 1] || p;
}

const OPTION_NAMES = ['--a', '--b', '--c']; // definition order

function usageLine() {
  return `usage: ${progName()} [-h] --a A --b B --c C`;
}

// Python repr() of a str: single quotes preferred, double quotes when the
// string contains ' but not "; escapes for backslash, \t, \n, \r and
// non-printable characters as \xHH.
function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (code >= 0x20 && code < 0x7f) out += ch;
    else out += `\\x${code.toString(16).padStart(2, '0')}`;
  }
  return out + quote;
}

// Print argparse's two-line error and exit(2).
function errorExit(message) {
  process.stderr.write(usageLine() + '\n');
  process.stderr.write(`${progName()}: error: ${message}\n`);
  process.exit(2);
}

// Print help to stdout and exit(0), like argparse's -h/--help action.
function printHelpAndExit() {
  const lines = [
    usageLine(),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
  ];
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

// Mimic Python int(str): strip whitespace, optional sign, digits only.
function parseIntValue(raw) {
  const trimmed = raw.trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    errorExit(`argument --c: invalid int value: ${pyStrRepr(raw)}`);
  }
  return BigInt(trimmed);
}

// Parse argv (already sliced, i.e. process.argv.slice(2)).
// Returns { a: string, b: string, c: BigInt } or exits on error/help.
export function parseArgs(argv) {
  const values = {}; // keyed by option name without dashes
  const extras = []; // unrecognized arguments, reported together

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelpAndExit();
    }

    // Split "--name=value" form; plain "--name" leaves inlineValue undefined.
    let name = token;
    let inlineValue;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
    }

    if (OPTION_NAMES.includes(name)) {
      let value;
      if (inlineValue !== undefined) {
        value = inlineValue;
      } else {
        if (i + 1 >= argv.length) {
          errorExit(`argument ${name}: expected one argument`);
        }
        value = argv[i + 1];
        i += 1;
      }
      values[name.slice(2)] = value;
    } else {
      extras.push(token);
    }
    i += 1;
  }

  if (extras.length > 0) {
    errorExit(`unrecognized arguments: ${extras.join(' ')}`);
  }

  // Report all missing required options, in definition order.
  const missing = OPTION_NAMES.filter((n) => !(n.slice(2) in values));
  if (missing.length > 0) {
    errorExit(`the following arguments are required: ${missing.join(', ')}`);
  }

  return { a: values.a, b: values.b, c: parseIntValue(values.c) };
}

export default parseArgs;

args.command:
node --input-type=module -e "
import { parseArgs } from '/output/lib/argparse.mjs';
process.argv[1] = '/output/bencode.mjs';

// 1. space-separated form
console.log(JSON.stringify(parseArgs(['--a','x','--b','y','--c','123456789012345678901234567890']), (k,v)=>typeof v==='bigint'?'BigInt('+v+')':v));

// 2. = form, negative int, reordered
console.log(JSON.stringify(parseArgs(['--c=-100','--b=hello','--a=world']), (k,v)=>typeof v==='bigint'?'BigInt('+v+')':v));

// 3. int() semantics: whitespace and + sign
console.log(String(parseArgs(['--a','1','--b','2','--c','  +42  ']).c));
"

node --input-type=module -e "
import { parseArgs } from '/output/lib/argparse.mjs';
process.argv[1] = '/output/bencode.mjs';
parseArgs(['--a','x']);
"; echo "exit=$?"
